export const classicButtonCSS = ":host{display:inline-block;vertical-align:middle;--studio-key-size:62px}\n    button{box-sizing:border-box;font:500 11px -apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;letter-spacing:.3px;cursor:default;background:linear-gradient(#4e5c6c,#354353);color:#ecf2f9;border:1px solid #7c8ea4;border-radius:4px;min-height:36px;padding:8px 14px;box-shadow:inset 0 1px 0 #ffffff15;display:inline-flex;align-items:center;justify-content:center;gap:10px}\n    button:disabled{opacity:.45}\n    :host([square]) button{width:var(--studio-key-size);height:var(--studio-key-size);min-height:0;border-radius:5px;border:1px solid #6c747f;box-shadow:inset 0 1px 0 #ffffff38,0 3px 0 #111417,0 5px 8px #0004;flex-direction:column;gap:7px;padding:5px;white-space:nowrap;background:linear-gradient(#4c535c,#353b43);color:#edf1f6}\n    :host([square]) button:active:not(:disabled){transform:translateY(1px)}\n    :host([variant=\"amber\"]) button{background:linear-gradient(#f8dfa8,#d9a556);color:#453318;border-color:#e5c18b}\n    :host([square][variant=\"play\"][pressed]) button{background:linear-gradient(#d3978c,#aa695e);color:#fff0e9;border-color:#dcaa9b}\n    :host([variant=\"delete\"]) button{background:#403638;color:#e0b4ad;border-color:#756066}\n    :host([variant=\"quit\"]) button{background:linear-gradient(#d3978c,#aa695e);color:#fff0e9;border-color:#dcaa9b}\n    :host([variant=\"refresh\"]) button{gap:5px;font-size:11px;padding:0;min-height:22px}\n    :host([led]) button{min-height:39px;padding:10px 16px;white-space:nowrap}\n    :host([square][led]) button{padding:5px;min-height:0}\n    .text{text-align:center;line-height:1.35}\n    .power-icon{display:none;width:22px;height:22px;flex:0 0 22px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;color:#88f5a7;filter:drop-shadow(0 0 2px #69e78eaa) drop-shadow(0 0 5px #69e78e66)}\n    :host([variant=\"power\"]) .power-icon{display:block}\n    :host([variant=\"power\"]) .led{display:none}\n    :host([variant=\"power\"][disabled]) .power-icon{color:#91a298;filter:none}\n    .led{display:none;width:8px;height:8px;flex:0 0 8px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff,#d9dee4 55%,#939da9);box-shadow:0 0 4px #ffffff35,inset 0 0 1px #fff}\n    :host([led]) .led{display:inline-block}\n    :host([led=\"green\"][pressed]) .led{background:radial-gradient(circle at 35% 30%,#dcffe5,#69e78e 55%,#27994b);box-shadow:0 0 5px #69e78e9c}\n    :host([led=\"red\"][pressed]) .led{background:radial-gradient(circle at 35% 30%,#ffd6ce,#f2796c 55%,#b42c28);box-shadow:0 0 5px #f2796c9c}\n";
export const nativeButtonCSS = "/* Shared native button geometry and LED lenses. Application context owns placement. */\n#studio-refined button:disabled{opacity:.45}\n#studio-refined .sr-key>i{font-size:22px;line-height:1}\n#studio-refined .sr-refresh>i{font-size:14px}\n#studio-refined button{font:500 11px -apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;letter-spacing:.3px;cursor:default}\n#studio-refined .sr-key{width:var(--sr-key-size);height:var(--sr-key-size);border-radius:5px;border:1px solid #6c747f;box-shadow:var(--sr-relief);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;padding:5px;white-space:nowrap}\n#studio-refined .sr-key:active{transform:translateY(1px)}\n#studio-refined .sr-key svg{width:18px;height:18px}\n#studio-refined .sr-power-icon{display:block;width:22px;height:22px;flex:0 0 22px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;color:#88f5a7;filter:drop-shadow(0 0 2px #69e78eaa) drop-shadow(0 0 5px #69e78e66)}\n#studio-refined .sr-small-button{background:linear-gradient(#4e5c6c,#354353);color:#ecf2f9;border:1px solid #7c8ea4;border-radius:4px;min-height:36px;padding:8px 14px;box-shadow:inset 0 1px 0 #ffffff15}\n#studio-refined .sr-key>span{text-align:center;line-height:1.35}\n#studio-refined .sr-refresh{display:inline-flex;align-items:center;gap:5px;font-size:11px;padding:0;min-height:22px}\n#studio-refined .sr-refresh svg{width:12px;height:12px}\n#studio-refined .sr-led-button{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:39px;padding:10px 16px;white-space:nowrap}\n/* All round status LEDs use the layer drawer's size, lens and glow. */\n#studio-refined{\n --sr-led-white:radial-gradient(circle at 35% 30%,#fff,#d9dee4 55%,#939da9);\n --sr-led-green:radial-gradient(circle at 35% 30%,#dcffe5,#69e78e 55%,#27994b);\n --sr-led-red:radial-gradient(circle at 35% 30%,#ffd6ce,#f2796c 55%,#b42c28);\n --sr-led-white-glow:0 0 4px #ffffff35,inset 0 0 1px #fff;\n --sr-led-green-glow:0 0 5px #69e78e9c;\n --sr-led-red-glow:0 0 5px #f2796c9c;\n}\n#studio-refined :is(.sr-led,.sr-air-dot,.sr-visibility-light,.sr-status-led){display:inline-block;width:8px;height:8px;flex:0 0 8px;border-radius:50%;background:var(--sr-led-white);box-shadow:var(--sr-led-white-glow)}\n#studio-refined :is(.sr-led:not(.sr-offline),.sr-layer-row:not(.is-off) .sr-visibility-light,.sr-led-button[aria-pressed=true] .sr-status-led){background:var(--sr-led-green);box-shadow:var(--sr-led-green-glow)}\n#studio-refined :is(.sr-air-dot:not(.not-live),:is(.sr-layer-mute,.sr-master-mute-button,.sr-layer-mono,.sr-audio-mute,.sr-audio-mono)[aria-pressed=true] .sr-status-led){background:var(--sr-led-red);box-shadow:var(--sr-led-red-glow)}\n";
export const graphiteButtonCSS = "/* Approved button material; used by native buttons and studio-button[skin=\"graphite\"]. */\n/* Approved graphite facade, matte keys and asymmetric monitor recess.\n   This stylesheet changes paint only; layout and the native preview rect stay intact. */\n#studio-refined {\n  --sr-key-size:var(--studio-key-size,62px);\n  --studio-face:radial-gradient(ellipse at 35% 0%,#67707925,transparent 75%),linear-gradient(135deg,#434b53,#30373f 55%,#262c33);\n  --studio-edge:#101418;\n  --studio-relief:inset 0 1px 1px #c5d0da3b,inset 1px 0 1px #c5d0da16,inset -2px -3px 4px #05080c88,0 1px 0 #080b0d,1px 3px 3px #000a,-1px -1px 1px #090c10;\n}\n#studio-refined :is(.sr-key,.sr-small-button) {\n  background:var(--studio-face);border-color:var(--studio-edge);box-shadow:var(--studio-relief);color:#c5cdd5;\n}\n#studio-refined .sr-key {border-radius:9px;color:#adb4bb;text-shadow:0 1px 1px #0005}\n#studio-refined .sr-small-button {border-radius:6px}\n#studio-refined .sr-key.sr-amber {color:#ffd077;text-shadow:0 0 2px #ffc15b70,0 0 8px #ffad2230}\n#studio-refined .sr-key.sr-red {color:#ff1427;text-shadow:0 0 2px #ff0b2380,0 0 8px #ff001d33}\n#studio-refined .sr-key.sr-green {color:#88f5a7;text-shadow:0 0 4px #69e78e50}\n#studio-refined .sr-small-button.sr-delete {color:#ff9b8e;text-shadow:0 0 5px #ff66551f}\n#studio-refined .sr-small-button.sr-quit {color:#ff9b8e}\n#studio-refined :is(.sr-key,.sr-small-button):active:not(:disabled) {\n  box-shadow:inset 0 1px 3px #0008,0 1px 1px #0009;\n}\n";
